WITH scored AS (SELECT *, SUM(amount) OVER (PARTITION BY merchant, account_id ORDER BY amount, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_sum_amount, MIN(amount) OVER (PARTITION BY merchant, account_id ORDER BY amount, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_min_amount, COUNT(amount) OVER (PARTITION BY merchant, account_id ORDER BY amount, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_count_amount, DENSE_RANK() OVER (PARTITION BY txn_type ORDER BY amount DESC NULLS LAST) AS amount_dense_rank FROM transactions) SELECT merchant, ROUND(AVG(amount_dense_rank), 2) AS avg_amount_dense_rank, COUNT(CASE WHEN merchant = '7-Eleven' THEN 1 END) AS 7_eleven_count, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, MIN(amount) AS min_amount, AVG(last7_sum_amount) FILTER (WHERE txn_type = 'FEE') AS fee_avg_last7_sum_amount, SUM(amount_dense_rank) FILTER (WHERE merchant = 'Amazon') AS amazon_total_amount_dense_rank FROM scored GROUP BY merchant ORDER BY fee_avg_last7_sum_amount DESC;
